// Visual + behavior check of the app shell against a running dev/preview server (replay mode).
//   NOTARY_PREVIEW_URL  base URL (default http://127.0.0.1:5175)
//   NOTARY_SCREENSHOTS  output dir (default screenshots/K3; gitignored)
//   NOTARY_VISUAL=quick only Certificates and one certificate at 1440 light + 390 dark
// Uses the system Chrome (channel "chrome"); no browser download.
import { chromium, expect } from "@playwright/test";
import { mkdir, writeFile, readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { computeContentHash } from "../../core/src/bundle/hash.ts";

const base = process.env.NOTARY_PREVIEW_URL ?? "http://127.0.0.1:5175";
const out = resolve(process.env.NOTARY_SCREENSHOTS ?? "screenshots/K3");
const quick = process.env.NOTARY_VISUAL === "quick";
await mkdir(out, { recursive: true });

const json = async (path) => JSON.parse(await readFile(new URL(`../public/${path}`, import.meta.url), "utf8"));
const guarded = await json("bundles/fixture/demo-run-guarded.json");
const notarize = await json("bundles/fixture/demo-notarize-dodo.json");
const changeApi = await json("bundles/fixture/demo-change-api-run-guarded.json");
const certs = await json("certificates/fixture/default/dodo.json");
const changeCerts = await json("certificates/fixture/change-api/dodo.json").catch(() => null);
const q = (run) => `?run=${encodeURIComponent(run)}`;
const enc = encodeURIComponent;

// Every page in src/routes.tsx, with record URLs taken from the published fixture data.
const cert = certs.certificates[0];
const revoked = changeCerts?.certificates.find((c) => c.status === "revoked");
const allPages = [
  { path: `/app/run${q(guarded.runId)}`, h1: "Run", slug: "run", detail: ".run-held" },
  { path: `/app/certificates${q(notarize.runId)}`, h1: "Certificates", slug: "certificates", detail: ".certs-grid" },
  { path: `/app/certificates/${enc(cert.id)}${q(notarize.runId)}`, h1: cert.claimId, slug: "certificate", detail: ".cert-pair" },
  ...(revoked
    ? [{ path: `/app/certificates/${enc(revoked.id)}${q(changeApi.runId)}`, h1: revoked.claimId, slug: "certificate-revoked", detail: ".revocation-block" }]
    : []),
  { path: `/app/approvals${q(guarded.runId)}`, h1: "Approvals", slug: "approvals", detail: ".desk-item" },
  { path: `/app/chat${q(guarded.runId)}`, h1: "Notary Chat", slug: "chat", detail: ".chat-suggestions" },
  { path: `/app/report${q(guarded.runId)}`, h1: "Report", slug: "report", detail: "#connections" },
];
const pages = quick ? allPages.filter((p) => p.slug.startsWith("certificate")) : allPages;
const matrix = quick
  ? [
      [1440, "light"],
      [390, "dark"],
    ]
  : [
      [1440, "light"],
      [1440, "dark"],
      [1024, "light"],
      [1024, "dark"],
      [390, "light"],
      [390, "dark"],
    ];
const settle = (page) =>
  page.evaluate(async () => {
    await document.fonts.ready;
    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  });

const browser = await chromium.launch({ channel: "chrome", headless: true });
const report = [];
try {
  for (const [width, theme] of matrix) {
    const context = await browser.newContext({
      viewport: { width, height: width === 1440 ? 1000 : 844 },
      reducedMotion: "reduce",
    });
    await context.addInitScript((t) => localStorage.setItem("notary-theme", t), theme);
    const page = await context.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    for (const p of pages) {
      await page.goto(`${base}${p.path}`);
      if (p.h1) await expect(page.getByRole("heading", { level: 1, name: p.h1, exact: true })).toBeVisible({ timeout: 30000 });
      else await page.waitForLoadState("networkidle");
      await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
      // Every page here shows a fixture run: the disclosure must be visible. No global mode chrome
      // (K3/K4): no app-wide replay banner is rendered at all, the sidebar has no mode item.
      await expect(page.locator(".fixture-banner").first()).toHaveText("Fixture data — simulated APIs, not a live run");
      await expect(page.locator(".replay-banner")).toHaveCount(0);
      if (width >= 768) {
        await expect(page.locator(".side-nav .side-item")).toHaveText([/^Run/, /^Certificates/, /^Approvals/, /^Chat/]);
        await expect(page.locator(".side")).not.toContainText(/Replay|Live/);
        await expect(page.locator(".side-foot").getByRole("link", { name: "Report" })).toBeVisible();
      }
      // Every page is built on the kit and opens with the sky band.
      await expect(page.locator(".ui-band-sky").first()).toBeVisible();
      await settle(page);
      const metrics = await page.evaluate(() => ({
        viewport: innerWidth,
        scroll: document.documentElement.scrollWidth,
        height: document.documentElement.scrollHeight,
        theme: document.documentElement.dataset.theme,
        heading: document.querySelector("h1")?.textContent,
      }));
      expect(metrics.scroll, `${p.path} overflows at ${width}`).toBeLessThanOrEqual(width);
      await page.screenshot({ path: resolve(out, `${p.slug}-${theme}-${width}.png`), fullPage: true, animations: "disabled" });
      if (p.detail) {
        const detail = page.locator(p.detail).first();
        if (await detail.count()) {
          await detail.scrollIntoViewIfNeeded();
          await page.screenshot({ path: resolve(out, `${p.slug}-${theme}-${width}-detail.png`), animations: "disabled" });
        }
      }
      report.push({ ...metrics, path: p.path, file: `${p.slug}-${theme}-${width}.png` });
    }

    // Phones: the navigation is a drawer opened by "Menu", closed by Escape (focus returns to Menu).
    if (width < 768) {
      await page.goto(`${base}/app/certificates${q(notarize.runId)}`);
      await page.getByRole("button", { name: "Menu" }).click();
      await expect(page.locator(".side-drawer")).toHaveAttribute("data-open", "true");
      await expect(page.locator(".side-drawer .side-search")).toBeFocused();
      await settle(page);
      await page.screenshot({ path: resolve(out, `drawer-${theme}-${width}.png`), animations: "disabled" });
      await page.keyboard.press("Escape");
      await expect(page.locator(".side-drawer")).not.toHaveAttribute("data-open", "true");
      await expect(page.getByRole("button", { name: "Menu" })).toBeFocused();
    }

    // Command palette lists records of the selected run.
    await page.goto(`${base}/app/certificates${q(notarize.runId)}`);
    await expect(page.getByRole("heading", { level: 1, name: "Certificates" })).toBeVisible();
    await page.keyboard.press("Control+k");
    await expect(page.getByRole("dialog", { name: "Search pages and records" })).toBeVisible();
    await page.keyboard.type(cert.id);
    await expect(page.locator("[cmdk-item]").first()).toContainText(cert.claimId);
    await page.screenshot({ path: resolve(out, `palette-${theme}-${width}.png`), animations: "disabled" });
    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(new RegExp(`/app/certificates/${cert.id}`));

    // The palette's Chat action opens Chat with the typed question prefilled (not sent).
    await page.keyboard.press("Control+k");
    await page.keyboard.type("Why was q02 held?");
    await page.getByRole("option", { name: /Ask Notary Chat: Why was q02 held\?/ }).click();
    await expect(page).toHaveURL(/\/app\/chat\?/);
    await expect(page.getByRole("textbox", { name: "Message Notary" })).toHaveValue("Why was q02 held?");
    await expect(page.locator(".chat-msg")).toHaveCount(0);

    // Chat in replay: the banner, a streamed answer with steps that collapse, an unavailable step.
    await page.goto(`${base}/app/chat${q(guarded.runId)}`);
    await expect(page.locator(".chat-banner")).toContainText("Replay — answers come from the recorded run, no live lookups");
    await page.getByRole("textbox", { name: "Message Notary" }).fill("Look up Acme Corp in Crustdata");
    await page.keyboard.press("Enter");
    await expect(page.locator(".chat-footer")).toBeVisible({ timeout: 20000 });
    await expect(page.locator('[data-slot="reasoning-steps-header"]')).toContainText(/Reasoned in \d+ steps?/);
    await page.locator('[data-slot="reasoning-steps-header"]').click();
    await expect(page.locator(".chat-step-fix", { hasText: "CRUSTDATA_API_KEY" }).first()).toBeVisible();
    await settle(page);
    await page.screenshot({ path: resolve(out, `chat-answer-${theme}-${width}.png`), animations: "disabled" });

    expect(errors).toEqual([]);
    await context.close();
  }

  // Tampered content is visibly withheld at the rendering boundary.
  const errorPage = await browser.newPage();
  await errorPage.route("**/bundles/sample-42.json", async (route) => {
    const response = await route.fetch();
    const data = await response.json();
    data.metrics.unsafe_actions_total += 1;
    await route.fulfill({ response, json: data });
  });
  await errorPage.goto(`${base}/app/certificates`);
  await expect(errorPage.getByRole("alert")).toContainText("hash mismatch");
  await errorPage.screenshot({ path: resolve(out, "integrity-error.png"), fullPage: true });
  await errorPage.close();

  // Old URLs redirect to the new pages and keep their query.
  const deepPage = await browser.newPage();
  const decision = guarded.decisions[0];
  for (const [from, to] of [
    [`/app${q(guarded.runId)}`, new RegExp(`/app/run\\?run=${guarded.runId}$`)],
    [`/app/queue/${enc(decision.id)}${q(guarded.runId)}`, new RegExp(`/app/run\\?run=${guarded.runId}&decision=${enc(decision.id)}$`)],
    [`/app/economics${q(guarded.runId)}`, new RegExp(`/app/report\\?run=${guarded.runId}$`)],
    [`/app/reports/dodo${q(notarize.runId)}`, new RegExp(`/app/certificates\\?run=${notarize.runId}&tool=dodo$`)],
    [`/app/beliefs/${enc(cert.beliefId)}${q(notarize.runId)}`, new RegExp(`/app/certificates/${cert.id}`)],
  ]) {
    await deepPage.goto(`${base}${from}`);
    await expect(deepPage, from).toHaveURL(to);
  }
  await deepPage.close();

  // Real bundles outrank fixtures by default and carry no fixture banner; cohorts stay apart.
  const liveRuns = await Promise.all(
    ["naive", "guarded"].map(async (variant) => {
      const data = await json(`bundles/fixture/demo-run-${variant}.json`);
      data.runId = `visual-real-${variant}`;
      data.sample = false;
      data.contentHash = computeContentHash(data);
      return data;
    }),
  );
  const realPage = await browser.newPage();
  await realPage.route("**/bundles/index.json", (route) =>
    route.fulfill({
      json: liveRuns.map((b) => ({
        runId: b.runId, kind: b.kind, mode: b.mode, variant: b.variant,
        sample: b.sample, status: b.status, startedAt: b.startedAt, contentHash: b.contentHash,
      })),
    }),
  );
  for (const run of liveRuns) await realPage.route(`**/bundles/${run.runId}.json`, (route) => route.fulfill({ json: run }));
  await realPage.goto(`${base}/app/report`);
  await expect(realPage.getByRole("combobox", { name: "Selected run" })).toHaveValue("visual-real-guarded");
  await expect(realPage.locator(".app-main > .fixture-banner")).toHaveCount(0);
  const groups = await realPage.locator(".run-picker optgroup").evaluateAll((els) =>
    els.map((g) => ({ label: g.label, runs: [...g.querySelectorAll("option")].map((o) => o.value) })),
  );
  expect(groups[0].runs.every((r) => r.startsWith("visual-real-"))).toBe(true);
  expect(groups[1].runs.every((r) => !r.startsWith("visual-real-"))).toBe(true);
  await realPage.close();

  await writeFile(resolve(out, "checks.json"), JSON.stringify(report, null, 2));
  console.log(
    `Reviewed ${report.length} route/theme/viewport combinations; no page errors or horizontal overflow. Sky bands, drawer, palette, Chat prefill and replay answer, tamper rejection, redirects and cohort separation passed. Screenshots: ${out}`,
  );
} finally {
  await browser.close();
}

// Screenshots for docs/screenshots/ (K4 visual loop): the landing (full length) and every dashboard
// page at 1440 and 390 px in the light theme, plus the dashboard at 1440 in the dark theme. Chat is
// captured mid-answer in replay (a question sent, steps streaming and expanded) by pausing the page
// clock between events. Runs against a production build served by `vite preview` (replay mode).
//   NOTARY_PREVIEW_URL  base URL (default http://127.0.0.1:5175)
//   NOTARY_SCREENSHOTS  output dir (default ../../docs/screenshots)
// Uses the system Chrome (channel "chrome"); no browser download.
import { chromium, expect } from "@playwright/test";
import { mkdir, readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const base = process.env.NOTARY_PREVIEW_URL ?? "http://127.0.0.1:5175";
const out = resolve(process.env.NOTARY_SCREENSHOTS ?? fileURLToPath(new URL("../../../docs/screenshots", import.meta.url)));
await mkdir(out, { recursive: true });

const json = async (path) => JSON.parse(await readFile(new URL(`../public/${path}`, import.meta.url), "utf8"));
const guarded = await json("bundles/fixture/demo-run-guarded.json");
const notarize = await json("bundles/fixture/demo-notarize-dodo.json");
const certs = await json("certificates/fixture/default/dodo.json");
const q = (run) => `?run=${encodeURIComponent(run)}`;
// The certificate with the most evidence (the record links come from the published data).
const cert = [...certs.certificates].sort((a, b) => b.evidence.length - a.evidence.length)[0];

const pages = [
  { slug: "run", path: `/app/run${q(guarded.runId)}`, h1: "Run" },
  { slug: "certificates", path: `/app/certificates${q(notarize.runId)}`, h1: "Certificates" },
  { slug: "certificate", path: `/app/certificates/${encodeURIComponent(cert.id)}${q(notarize.runId)}`, h1: cert.claimId },
  { slug: "approvals", path: `/app/approvals${q(guarded.runId)}`, h1: "Approvals" },
  { slug: "report", path: `/app/report${q(guarded.runId)}`, h1: "Report" },
];
// `frames: false` on a page whose clock is paused (its requestAnimationFrame is paused too).
const settle = (page, frames = true) =>
  page.evaluate(async (f) => {
    await document.fonts.ready;
    if (f) await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  }, frames);
const overflow = (page) => page.evaluate(() => document.documentElement.scrollWidth - innerWidth);

const browser = await chromium.launch({ channel: "chrome", headless: true });
const written = [];
const shoot = async (page, name, { frames = true, ...opts } = {}) => {
  await settle(page, frames);
  const extra = await overflow(page);
  if (extra > 0) throw new Error(`${name}: horizontal overflow of ${extra}px`);
  const path = resolve(out, `${name}.png`);
  await page.screenshot({ path, animations: "disabled", ...opts });
  written.push(`${name}.png`);
};

try {
  for (const [width, theme] of [
    [1440, "light"],
    [390, "light"],
    [1440, "dark"],
  ]) {
    const suffix = theme === "dark" ? `${width}-dark` : `${width}`;
    const context = await browser.newContext({ viewport: { width, height: width === 1440 ? 900 : 844 }, reducedMotion: "reduce" });
    await context.addInitScript((t) => localStorage.setItem("notary-theme", t), theme);
    const page = await context.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));

    // The landing is pinned to the light theme; one full-length capture per width.
    if (theme === "light") {
      await page.goto(`${base}/`);
      // Scroll through once so every lazy section and its data load, then return to the top.
      await page.evaluate(async () => {
        await document.fonts.ready;
        for (let y = 0; y < document.documentElement.scrollHeight; y += 400) {
          scrollTo(0, y);
          await new Promise((r) => setTimeout(r, 120));
        }
      });
      await page.locator(".l-mini-held .l-mini-actions").first().waitFor({ state: "attached", timeout: 30000 });
      await page.waitForTimeout(800);
      await page.evaluate(() => scrollTo(0, 0));
      await shoot(page, `landing-${suffix}`, { fullPage: true });
    }

    for (const p of pages) {
      await page.goto(`${base}${p.path}`);
      await expect(page.getByRole("heading", { level: 1, name: p.h1, exact: true })).toBeVisible({ timeout: 30000 });
      await page.waitForLoadState("networkidle");
      // The Run page replays the recorded timeline at 1x; show the whole run instead of a moment of it.
      if (p.slug === "run") {
        await page.getByRole("button", { name: "Instant" }).click();
        await expect(page.locator(".run-waiting")).toHaveCount(0, { timeout: 30000 });
      }
      await shoot(page, `${p.slug}-${suffix}`, { fullPage: true });
    }

    // Chat mid-answer: send a question in replay, then advance a paused page clock (fresh tab) until
    // the steps have streamed and the answer is part-written, with the steps expanded.
    const chatContext = await browser.newContext({ viewport: { width, height: width === 1440 ? 900 : 844 }, reducedMotion: "reduce" });
    await chatContext.addInitScript((t) => localStorage.setItem("notary-theme", t), theme);
    const chat = await chatContext.newPage();
    chat.on("pageerror", (e) => errors.push(e.message));
    await chat.clock.install();
    await chat.goto(`${base}/app/chat${q(guarded.runId)}`);
    await expect(chat.getByRole("heading", { level: 1, name: "Notary Chat", exact: true })).toBeVisible({ timeout: 30000 });
    await chat.waitForLoadState("networkidle");
    await chat.clock.pauseAt(Date.now() + 1000);
    await chat.getByRole("textbox", { name: "Message Notary" }).fill("Why was refund q02 held?");
    await chat.keyboard.press("Enter");
    let state = { steps: 0, text: 0, footer: false };
    for (let i = 0; i < 200 && !(state.steps >= 3 && state.text > 900); i++) {
      await chat.clock.runFor(20);
      state = await chat.evaluate(() => ({
        steps: Number(document.querySelector('[data-slot="reasoning-steps"]')?.getAttribute("data-stage-count") ?? 0),
        text: document.querySelector(".chat-msg-assistant")?.textContent?.length ?? 0,
        footer: !!document.querySelector(".chat-footer"),
      }));
    }
    if (state.footer || state.steps < 3) throw new Error(`chat: not captured mid-answer (${JSON.stringify(state)})`);
    if (!(await chat.locator('[data-slot="reasoning-steps"]').first().getAttribute("data-open"))) await chat.locator('[data-slot="reasoning-steps-header"]').first().click();
    await shoot(chat, `chat-${suffix}`, { frames: false });
    await chatContext.close();

    if (errors.length) throw new Error(`${width} ${theme}: ${errors.join("; ")}`);
    await context.close();
  }
  console.log(`Wrote ${written.length} screenshots to ${out}:\n  ${written.join("\n  ")}`);
} finally {
  await browser.close();
}
# Component credits

All files below were selected by browsing the UIAble collection on
[21st.dev](https://preview.21st.dev/@uiable/library/uiable), inspected, and installed
with the **shadcn CLI 4.21.4** using their public registry URLs. Installation ran in
`packages/web/registry-stage` to preserve the existing dashboard primitives.
The registry files remain there as ignored local review material. The adapted
components are committed under `src/components/landing`.

Each selected item belongs to [CodedThemes/UIAble](https://github.com/codedthemes/uiable).
The publisher's [MIT license](https://github.com/codedthemes/uiable/blob/master/LICENSE)
was checked for each item against its source paths. Copyright (c) 2026 CodedThemes.
The full required notice is preserved in [LICENSE-uiable.txt](LICENSE-uiable.txt).
Source paths, registry dependencies and registry URLs are recorded in
[registry-sources.json](registry-sources.json).

| Section          | Installed component / source URL                                                                                                           | Adapted file      | License |
| ---------------- | ------------------------------------------------------------------------------------------------------------------------------------------ | ----------------- | ------- |
| Hero             | [Hero 3](https://uiable.com/r/block-hero-3.json)                                                                                           | Hero.tsx          | MIT     |
| Problem bento    | [Financial Bento Grid](https://uiable.com/r/block-bento-5.json), [21st.dev listing](https://mcp.21st.dev/@uiable/components/block-bento-5) | ProblemBento.tsx  | MIT     |
| Numbered process | [Process 1](https://uiable.com/r/block-process-1.json)                                                                                     | ProcessSteps.tsx  | MIT     |
| Results strip    | [Statistics 1](https://uiable.com/r/block-statistics-1.json)                                                                               | ResultsStrip.tsx  | MIT     |
| CTA              | [CTA 1](https://uiable.com/r/block-cta-1.json)                                                                                             | FinalCTA.tsx      | MIT     |
| Footer           | [Footer 2](https://uiable.com/r/block-footer-2.json)                                                                                       | LandingFooter.tsx | MIT     |

These are substantial adaptations, not unchanged drop-ins. Responsive section
composition, card groupings, process connectors, statistic columns, CTA and footer
organization informed the final components. Sample business figures, unrelated
images, sponsor marks, contact forms, carousel/counting animations and decorative
icons were removed. Notary's Geist type, warm neutral tokens, blue accent, rounded
cards, shadcn Button/Card and real bundle/evidence data replace the defaults.
No borrowed image assets are shipped. No unverified live claims are added.

The only new runtime dependency retained is `react-router` **8.4.0**, pinned
exactly. The development runner `tsx` **4.23.15** is also pinned exactly and lets the visual checks reuse the shared TypeScript hash function. Registry-only dependencies are confined to the ignored installation
staging directory and are not shipped. Existing dependency ranges are unchanged.

Installation command (from packages/web):

```powershell
npm exec --yes --package=shadcn@4.21.4 -- shadcn add https://uiable.com/r/block-hero-3.json https://uiable.com/r/block-bento-5.json https://uiable.com/r/block-process-1.json https://uiable.com/r/block-statistics-1.json https://uiable.com/r/block-cta-1.json https://uiable.com/r/block-footer-2.json --cwd registry-stage --yes
```

The numbered process markers are structural step positions requested by the user,
not product statistics. The supplied hero anecdote includes its requested HTTP
status. All measured result values come from verified bundles, and tool copy and
status come from public/evidence/evidence.json. Fixture results include both the
persistent AGENTS.md disclosure and the requested planted-quirks label.

## U6 — Dither Kit

Graphs and the blue card wash use actual [Dither Kit](https://www.tripwire.sh/dither-kit)
source, installed with shadcn CLI 4.21.4 from these publisher registry URLs:

- https://www.tripwire.sh/r/core.json
