// THE route table for /app. Sidebar, top bar title, document titles, the command palette and the
// router all read it. Six pages are in the sidebar (Run, Certificates, Approvals, Business, Incidents, Chat); Report is
// linked from the sidebar footer; a certificate has its own page.
import type { ReactElement } from "react";
import { matchPath } from "react-router";
import { RunPage } from "./pages/run/RunPage";
import { CertificatesPage } from "./pages/certificates/CertificatesPage";
import { CertificateDetailPage } from "./pages/certificates/CertificateDetailPage";
import { ApprovalsPage } from "./pages/approvals";
import { ChatPage } from "./pages/chat/ChatPage";
import { BusinessPage } from "./pages/business/BusinessPage";
import { IncidentsPage } from "./pages/incidents/IncidentsPage";
import { ReportPage } from "./pages/report/ReportPage";

export type AppRoute = {
  id: string;
  /** Absolute path under /app; `:param` segments name the record. */
  path: string;
  title: string;
  description: string;
  /** In the sidebar (exactly six routes). */
  nav?: boolean;
  /** Sidebar count: approvals waiting for a human. */
  badge?: "approvals";
  /** Route id of the list page a record belongs to (top bar trail; switching runs returns there). */
  parent?: string;
  /** Record kind this route renders, for routes with a `:param`. */
  record?: "certificate";
  /** Renders without a selected, verified run (it handles empty and loading states itself). */
  ungated?: boolean;
  element: ReactElement;
};

export const routes: AppRoute[] = [
  { id: "run", path: "/app/run", title: "Run", description: "One run, step by step: what the agent did and why.", nav: true, ungated: true, element: <RunPage /> },
  { id: "certificates", path: "/app/certificates", title: "Certificates", description: "API behavior certified within a scope, and revocable.", nav: true, element: <CertificatesPage /> },
  { id: "certificate", path: "/app/certificates/:certificateId", title: "Certificate", description: "One certificate and the evidence behind it.", parent: "certificates", record: "certificate", element: <CertificateDetailPage /> },
  { id: "approvals", path: "/app/approvals", title: "Approvals", description: "Held money actions waiting for a human.", nav: true, badge: "approvals", element: <ApprovalsPage /> },
  { id: "business", path: "/app/business", title: "Business", description: "Unit economics from real runs and the business plan modeled in cfo.ai.", nav: true, ungated: true, element: <BusinessPage /> },
  { id: "incidents", path: "/app/incidents", title: "Incidents", description: "What went wrong while the agents worked, and how it was resolved.", nav: true, ungated: true, element: <IncidentsPage /> },
  { id: "chat", path: "/app/chat", title: "Chat", description: "Ask Notary about runs, certificates and the APIs it checks; answers cite records.", nav: true, ungated: true, element: <ChatPage /> },
  { id: "report", path: "/app/report", title: "Report", description: "Run comparison, cost per run, connections and receipts.", ungated: true, element: <ReportPage /> },
];

/** The sidebar, in order. */
export const navRoutes = () => routes.filter((r) => r.nav);

export type Redirect = {
  from: string;
  /** Target path (may carry a query); `:param` values of `from` are substituted. */
  to: string;
};

/**
 * Old URLs, kept working for shared links. The old query string is kept and merged with the
 * target's (the target's own params win, e.g. ?run= of /app/runs/:runId).
 */
export const redirects: Redirect[] = [
  { from: "/app", to: "/app/run" },
  { from: "/app/overview", to: "/app/run" },
  { from: "/app/mission-control", to: "/app/run" },
  { from: "/app/runs", to: "/app/run" },
  { from: "/app/runs/:runId", to: "/app/run?run=:runId" },
  { from: "/app/queue", to: "/app/run" },
  { from: "/app/queue/:decisionId", to: "/app/run?decision=:decisionId" },
  { from: "/app/probes", to: "/app/run" },
  { from: "/app/probes/:probeId", to: "/app/run?probe=:probeId" },
  { from: "/app/beliefs", to: "/app/certificates" },
  { from: "/app/beliefs/:beliefId", to: "/app/certificates?belief=:beliefId" },
  { from: "/app/reports", to: "/app/certificates" },
  { from: "/app/reports/:tool", to: "/app/certificates?tool=:tool" },
  { from: "/app/api-report", to: "/app/certificates" },
  { from: "/app/revocation-demo", to: "/app/certificates" },
  { from: "/app/revocation", to: "/app/certificates" },
  { from: "/app/economics", to: "/app/business" },
  { from: "/app/evidence", to: "/app/report" },
  { from: "/app/comparison", to: "/app/report" },
  { from: "/app/ask", to: "/app/chat" },
];

/** The target of a redirect for concrete params, old query merged (target params win). */
export function redirectTarget(r: Redirect, params: Record<string, string | undefined>, search = ""): string {
  const filled = r.to.replace(/:([A-Za-z]+)/g, (_, name: string) => encodeURIComponent(params[name] ?? ""));
  const [path, query = ""] = filled.split("?", 2) as [string, string?];
  const merged = new URLSearchParams(search);
  for (const [k, v] of new URLSearchParams(query)) merged.set(k, v);
  const q = merged.toString();
  return q ? `${path}?${q}` : path;
}

export const routeById = (id: string) => routes.find((r) => r.id === id);

/** The route (and its params) for a pathname. Most specific match wins. */
export function matchAppRoute(
  pathname: string,
): { route: AppRoute; params: Record<string, string | undefined> } | undefined {
  const normalized = pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname;
  for (const route of [...routes].sort((a, b) => b.path.split("/").length - a.path.split("/").length)) {
    const m = matchPath({ path: route.path, end: true }, normalized);
    if (m) return { route, params: m.params };
  }
  return undefined;
}

/** Path relative to the /app/* splat, for <Route path>. */
export const relativePath = (path: string) => (path === "/app" ? "" : path.replace(/^\/app\//, ""));
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Link, useLocation } from "react-router";
import { Toaster } from "sonner";
import { Button, EmptyState, FixtureNote, NoRunsYet, Page, PageBody, PageHeader, PageHeaderContext, PageSkeleton, StatusPill } from "../../ui";
import { CommandPalette } from "./CommandPalette";
import { MobileBar, Sidebar } from "./Sidebar";
import { ShellStatusProvider } from "./status";
import { useData } from "../../app/catalog";
import { LiveToasts } from "../../app/live-toasts";
import { keepView, NO_RUNS_COMMANDS, withRun } from "../../app/links";
import { matchAppRoute, routeById, type AppRoute } from "../../routes";
import { dateTime as date } from "../../lib/time";
import "./shell.css";

/** Trail for the current route: list page › record id (or just the page title). */
export function useCrumbs(): { label: string; path?: string }[] {
  const { pathname } = useLocation();
  const match = matchAppRoute(pathname);
  if (!match) return [{ label: "Not found" }];
  const chain: AppRoute[] = [];
  let r: AppRoute | undefined = match.route;
  while (r) {
    chain.unshift(r);
    r = r.parent ? routeById(r.parent) : undefined;
  }
  const record = Object.values(match.params)[0];
  return chain.map((c, i) => ({
    label: i === chain.length - 1 && record ? decodeURIComponent(record) : c.title,
    path: i === chain.length - 1 ? undefined : c.path,
  }));
}

/** Record pages: a link back to the list, above the page title. */
function Breadcrumb() {
  const crumbs = useCrumbs();
  const { selectedRunId } = useData();
  if (crumbs.length < 2) return null;
  return (
    <nav className="band-crumbs" aria-label="Breadcrumb">
      <ol>
        {crumbs.map((c, i) => (
          <li key={i} aria-current={i === crumbs.length - 1 ? "page" : undefined}>
            {c.path ? <Link to={withRun(c.path, selectedRunId)}>{c.label}</Link> : <span>{c.label}</span>}
          </li>
        ))}
      </ol>
    </nav>
  );
}

/** Integrity receipt of the selected run: verified hash, kind, status and provenance. */
export function RunReceipt() {
  const { bundle } = useData();
  if (!bundle) return null;
  return (
    <div className="run-receipt">
      <span>
        Hash verified in this browser{" "}
        <code title={bundle.contentHash}>{bundle.contentHash.slice(0, 12)}…</code>
      </span>
      <span>
        {bundle.runId} · {bundle.kind} / {bundle.variant}
      </span>
      <StatusPill value={bundle.status} />
      <span>{date(bundle.startedAt)}</span>
    </div>
  );
}

/**
 * Nothing to show: no real run is published (or, under ?fixtures=1, no fixture run). Never a
 * fallback to fixture data. The page keeps its title so the shell still reads as that page.
 */
export function NoRunsPage({ title, fixtures }: { title: string; fixtures: boolean }) {
  return (
    <Page>
      <PageHeader title={title} summary={fixtures ? "No fixture runs are published" : "No runs recorded yet"} />
      <PageBody>
        {fixtures ? (
          <EmptyState
            title="No fixture runs published"
            action={
              <Button variant="secondary" asChild>
                <Link to="/app/run">Show recorded runs</Link>
              </Button>
            }
          >
            The fixture view lists <code>sample: true</code> bundles only, and none are published. Remove{" "}
            <code>?fixtures=1</code> to see recorded runs.
          </EmptyState>
        ) : (
          <NoRunsYet
            commands={NO_RUNS_COMMANDS}
            action={
              <Button variant="secondary" asChild>
                <Link to="/app/report">Check connections</Link>
              </Button>
            }
          />
        )}
      </PageBody>
    </Page>
  );
}

/** Routes that stay useful with no run: Report (connections) and, against a live server, Run (it starts runs). */
function worksWithoutRuns(routeId: string | undefined, source: "api" | "static"): boolean {
  return routeId === "report" || (routeId === "run" && source === "api");
}

function Gate({ children, ungated, routeId, title }: { children: ReactNode; ungated: boolean; routeId?: string; title: string }) {
  const { loading, error, bundles, missingRunId, reload, running, fixtures, source } = useData();
  const empty = !loading && !error && !bundles.length && !running.length;
  if (empty && !worksWithoutRuns(routeId, source)) return <NoRunsPage title={title} fixtures={fixtures} />;
  if (ungated) return <>{children}</>;
  if (loading) return <PageSkeleton label="Verifying bundle integrity…" />;
  if (error)
    return (
      <EmptyState tone="error" title="Runs withheld" action={<Button onClick={reload}>Retry loading</Button>}>
        <p>A published run failed its integrity check in this browser, so nothing from it is shown. Re-export it with <code>pnpm notary export</code>.</p>
        <p className="gate-detail">{error}</p>
      </EmptyState>
    );
  if (!bundles.length) return <NoRunsPage title={title} fixtures={fixtures} />;
  // A live run that is still running has no bundle yet; it is not "unpublished".
  if (missingRunId && !running.some((r) => r.runId === missingRunId))
    return (
      <EmptyState
        tone="error"
        title={`Run ${missingRunId} is not published`}
        action={
          <Button asChild>
            <Link to={keepView("/app/run")}>Open the default run</Link>
          </Button>
        }
      >
        The link names a run that is not in the hash-verified catalog. Open the default run or pick one from the list.
      </EmptyState>
    );
  return <>{children}</>;
}

/**
 * The dashboard frame: a quiet sidebar (phones: a top bar with a drawer), the white page, the
 * command palette and toasts. Light only. Only real runs are shown; fixture runs appear only in the
 * development-only `?fixtures=1` view, and there every page header carries the fixture disclosure
 * (one small pill on the summary line, present only when the selected run is fixture data). The
 * data mode is not repeated as chrome: pages say what fails without a live server where it would.
 */
export function AppShell({ children }: { children: ReactNode }) {
  const [paletteOpen, setPaletteOpen] = useState(false);
  const { bundle } = useData();
  const { pathname } = useLocation();
  const match = matchAppRoute(pathname);
  useEffect(() => {
    document.title = `${match?.route.title ?? "Not found"} · Notary`;
  }, [match?.route.title]);
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  const sample = !!bundle?.sample;
  const header = useMemo(
    () => ({ inShell: true, lead: <Breadcrumb />, note: sample ? <FixtureNote className="fixture-banner" /> : undefined }),
    [sample],
  );
  const openPalette = () => setPaletteOpen(true);
  return (
    <ShellStatusProvider>
      <div className="app-shell">
        <a className="skip" href="#main">
          Skip to content
        </a>
        <Sidebar onPalette={openPalette} />
        <div className="app-column">
          <MobileBar onPalette={openPalette} />
          <main id="main" className="app-main" tabIndex={-1}>
            <PageHeaderContext.Provider value={header}>
              <Gate ungated={!!match?.route.ungated} routeId={match?.route.id} title={match?.route.title ?? "Notary"}>
                {children}
              </Gate>
            </PageHeaderContext.Provider>
          </main>
        </div>
        <CommandPalette open={paletteOpen} onOpenChange={setPaletteOpen} />
        <Toaster theme="light" position="bottom-right" />
        <LiveToasts />
      </div>
    </ShellStatusProvider>
  );
}
// The sidebar: "Notary" in Instrument Serif, search, the selected-run switcher, the four pages
// (Run, Certificates, Approvals with its count, Chat) on Rare UI's Hook Sidebar (an accent rail that
