// `(...)` groups are raw regex; everything outside them is a literal path with named params.
const pattern = source
  .split(/(\([^)]*\))/)
  .map((part) =>
    part.startsWith("(")
      ? part
      : part
          .replace(/[.+?^${}|[\]\\]/g, "\\$&")
          .replace(/:[A-Za-z]+\*/g, ".*")
          .replace(/:[A-Za-z]+/g, "[^/]+"),
  )
  .join("");
return new RegExp(`^${pattern}$`);

